protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    // Validate edges belong to graph
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " not in graph");
        }
    }
    boolean directed = graph.isDirected();
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        if (directed) {
            adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        } else {
            adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
            adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
        }
    }
    // start vertex
    E firstEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(firstEdge);
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>();
    V current = startVertex;
    vertexList.add(current);
    while (usedEdges.size() < tour.size()) {
        List<E> edges = adjacency.get(current);
        if (edges == null) {
            return null;
        }
        E nextEdge = null;
        for (E e : edges) {
            if (!usedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            return null;
        }
        usedEdges.add(nextEdge);
        edgeList.add(nextEdge);
        V nextVertex;
        if (directed) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        } else {
            V u = graph.getEdgeSource(nextEdge);
            V v = graph.getEdgeTarget(nextEdge);
            nextVertex = u.equals(current) ? v : u;
        }
        current = nextVertex;
        vertexList.add(current);
    }
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new org.jgrapht.traverse.GraphPathImpl<>(graph, startVertex, current, weight, vertexList, edgeList);
}
